arguments.command:
cat > /tmp/fw/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  Username*) echo "x-access-token" ;;
  Password*) echo "$GITHUB_TOKEN" ;;
  *) echo "" ;;
esac
EOF
chmod +x /tmp/fw/askpass.sh
cd /tmp/fw/ross
GIT_ASKPASS=/tmp/fw/askpass.sh GIT_TERMINAL_PROMPT=0 timeout 90 git push --dry-run origin HEAD:refs/heads/friend/ross 2>&1 | tail -3
